import * as C from './core.js';
import {Store} from './store.js';
const {$,esc}={ $:s=>document.querySelector(s),esc:C.esc};
const store=new Store();let tab='대시보드',date=C.today(),selected=[],dashMode='normal',checks=new Set(),compact=false,calendarMode='month',calendarDate=C.today(),calendarFilters={events:true,time:true,tasks:true,detail:true};
let recordFilters={from:C.today(),to:C.today(),student:'',kind:'',tag:'',area:'',q:''};
let actions=new Map(),actionNo=0,saveNotice='',locked=false,dragSlot=null,clockTimer;
const db=()=>store.db,settings=()=>db().settings[0],students=()=>C.activeStudents(db());
const kindLabel=k=>({지도:'조언',관찰:'기록',추가기록:'추가 기록'}[k]||k);
const name=id=>{const s=db().students.find(x=>x.id===id);return s?(s.deletedAt?'(나간 학생) ':'')+s.no+'. '+s.name:'(나간 학생)'};
const btn=(label,fn,cls='',attrs='')=>{const id=String(++actionNo);actions.set(id,fn);return `<button type="button" class="${cls}" data-action="${id}" ${attrs}>${label}</button>`};
const badge=x=>`<span class="badge">${esc(x)}</span>`;
const empty=(title,desc='')=>`<div class="empty"><h3>${esc(title)}</h3>${esc(desc)}</div>`;
const opts=(values,value)=>values.map(v=>{const [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${String(value)===String(key)?'selected':''}>${esc(label)}</option>`}).join('');
const input=(label,key,value='',type='text',attrs='')=>`<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,key,values,value='')=>`<label>${label}<select name="${key}">${opts(values,value)}</select></label>`;
const textarea=(label,key,value='')=>`<label>${label}<textarea name="${key}">${esc(value)}</textarea></label>`;
const checkbox=(label,key,value=false)=>`<label class="inline"><input type="checkbox" name="${key}" ${value?'checked':''}>${label}</label>`;
const multiple=(list,key,values=[])=>`<div class="checkgrid">${list.map(([id,label])=>`<label class="inline"><input type="checkbox" name="${key}" value="${esc(id)}" ${values.includes(id)?'checked':''}>${esc(label)}</label>`).join('')}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500)}
async function run(fn){try{await fn()}catch(e){toast(e.message||String(e));console.error(e)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.stopPropagation();run(()=>actions.get(b.dataset.action)?.(e))}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!$('#modal').open&&!locked){e.preventDefault();$('#quick-text')?.focus()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.student[data-action]')){e.preventDefault();run(()=>actions.get(e.target.dataset.action)?.(e))}});
function closeModal(){$('#modal').close();$('#modal').innerHTML=''}
function modal(title,body,onSubmit=null,save='저장'){const el=$('#modal');el.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${btn('닫기',closeModal)}</div><div class="dialog-body">${onSubmit?'<form id="modal-form">':''}${body}${onSubmit?`<div class="dialog-foot">${btn('취소',closeModal)}<button class="primary" type="submit">${save}</button></div></form>`:''}</div>`;if(!el.open)el.showModal();if(onSubmit){$('#modal-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const data=new FormData(f);f.querySelector('[type=submit]').disabled=true;try{await onSubmit(data,f)}catch(err){toast(err.message)}finally{if(f.isConnected)f.querySelector('[type=submit]').disabled=false}}}return el}
async function commit(ops,message='저장했습니다.'){await store.commit(ops);saveNotice=`저장 ${new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}`;render();if(message)toast(message)}
const up=(table,data)=>({table,id:data.id,data});
function header(){return `<header class="top"><div class="brand"><span class="logo">ST</span><strong>오늘의 별</strong><small>${esc(settings().className)}</small></div><div class="row"><span class="saved">${esc(store.mode==='demo'?'체험 모드 · 이 기기에만 저장':saveNotice||'클라우드 연결됨')}</span>${btn('새로고침',async()=>{if(store.mode==='cloud'){await store.load();render();toast('최신 자료를 불러왔습니다.')}})}${btn('교실 화면',classroom)}${btn('로그아웃',async()=>{await store.logout();selected=[];render()})}</div></header>`}
function render(){if(locked)return;document.querySelector('.print-root')?.remove();document.body.classList.remove('report-open');if(!db()){renderLogin();return}$('#app').innerHTML=header()+`<div class="shell"><div class="quick-wrap"><form class="quick" id="quick-form"><input id="quick-text" aria-label="빠른 기록 입력" placeholder="예: 3번 2교시 친구를 도와줌 · / 키로 바로 입력" autocomplete="off"><select id="quick-period" aria-label="교시">${opts(['자동','아침',...Array.from({length:7},(_,i)=>`${i+1}교시`),'점심','방과후','기타'],'자동')}</select><button class="primary">기록 확인</button></form>${selected.length?`<div class="chips" style="padding-top:7px">${selected.map(id=>btn(esc(name(id))+' ×',()=>{selected=selected.filter(x=>x!==id);render()})).join('')}${btn('선택 해제',()=>{selected=[];render()})}</div>`:''}</div><nav class="tabs" aria-label="주 메뉴">${['대시보드','기록','시간표·일정','과제','루틴','학생','자리','설정'].map(t=>btn(t,()=>{tab=t;render()},tab===t?'active':'',tab===t?'aria-current="page"':'')).join('')}</nav>${store.mode==='demo'?'<div class="notice">가상 명단으로 체험 중입니다. 이 모드의 자료는 이 브라우저에만 저장됩니다. 실제 학급은 수파베이스 연결 후 구글 로그인으로 사용하세요.</div>':''}${settings().lastBackupAt&&Date.now()-new Date(settings().lastBackupAt)>7*86400000?'<div class="notice">마지막 백업 후 7일이 지났습니다. 설정에서 백업 파일을 내려받으세요.</div>':!settings().lastBackupAt?'<div class="muted" style="margin-bottom:10px">아직 백업하지 않았습니다. 설정에서 전체 자료를 내보낼 수 있습니다.</div>':''}<main id="main">${({'대시보드':dashboard,'기록':recordsView,'시간표·일정':calendarView,'과제':assignmentsView,'루틴':routinesView,'학생':studentsView,'자리':seatsView,'설정':settingsView}[tab])()}</main></div>${selected.length&&dashMode==='normal'?`<aside class="bulkbar"><div><strong>${selected.length}명 선택</strong><small> · ${selected.map(name).map(esc).join(', ')}</small></div><div class="row">${btn('+1 칭찬',()=>bulkRecord('칭찬'))}${btn('0 기록',()=>bulkRecord('관찰'))}${btn('−1 조언',()=>bulkRecord('지도'))}</div></aside>`:''}`;
 $('#quick-form').onsubmit=e=>{e.preventDefault();const text=$('#quick-text').value.trim();if(!text&&!selected.length)return toast('내용을 입력하거나 학생을 선택하세요.');const parsed=C.parseInput(text,db(),selected);parsed.date=date;const period=$('#quick-period').value;if(period!=='자동')parsed.period=period;recordEditor(parsed)};
 document.querySelectorAll('[data-drop]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(dragSlot)run(()=>swapSlots(dragSlot,el.dataset.drop));dragSlot=null}});
 document.querySelectorAll('[data-drag]').forEach(el=>{el.ondragstart=e=>{dragSlot=el.dataset.drag;e.dataTransfer.setData('text/plain',dragSlot)};el.onpointerdown=e=>{if(e.pointerType==='touch'){el._touchTimer=setTimeout(()=>{dragSlot=el.dataset.drag;toast('이동할 교시를 누르세요.');},550)}};el.onpointerup=()=>clearTimeout(el._touchTimer);el.onpointercancel=()=>clearTimeout(el._touchTimer)});
}
function renderLogin(){clearInterval(clockTimer);$('#app').innerHTML=`<div class="panel login"><span class="logo">ST</span><h1>오늘의 별</h1><p>오늘의 작은 행동을 기록하고,<br>아이들의 성장을 함께 살펴보세요.</p><p>생활지도 기록 · 과제와 루틴 · 시간표와 일정<br>선생님의 학급 운영을 한곳에서 관리합니다.</p>${store.client?btn('구글 계정으로 시작하기',()=>store.login(),'primary'):'<div class="notice">아직 연결 전입니다. config.js에 수파베이스 프로젝트 주소와 공개 키를 입력하면 구글 로그인이 활성화됩니다.</div>'}${btn('가상 명단으로 먼저 살펴보기',()=>{store.demo();render()})}<small>연결 전 체험 자료와 로그인 후 학급 자료는 별도로 관리됩니다.</small></div>`}
function periodInfo(slot){const rule=db().subject_rules.find(x=>x.code===slot?.subjectCode);let teacher=rule?.teacherName||'';if(rule?.teacherHistory?.length){const versions=rule.teacherHistory.filter(h=>h.from<=slot.date).sort((a,b)=>b.from.localeCompare(a.from));teacher=versions[0]?.name||''}return {rule,teacher:slot?.teacherOverride||teacher,location:slot?.locationOverride||rule?.location||'',type:slot?.type||rule?.defaultType||'일반'}}
function timeSlots(d,calendar=false){return Array.from({length:6},(_,i)=>{const p=i+1,slot=db().timetables.find(t=>t.date===d&&t.period===p),info=periodInfo(slot),events=db().events.filter(e=>e.date===d&&e.period===p);const content=`<small>${p}교시${calendar?'':' · '+esc(settings().periodTimes?.[i]||'')}</small> <strong>${esc(slot?(calendar&&!calendarFilters.detail?info.rule?.label||slot.subjectCode[0]:slot.subjectCode):'—')}</strong>${events.map(e=>`<div>${esc(e.title)}</div>`).join('')}${info.type!=='일반'?badge(info.type):''}${(!calendar||calendarFilters.detail)?`<small>${esc([settings().timetableDisplay.showLocation?info.location:'',settings().timetableDisplay.showTeacher?info.teacher:'',slot?.memo].filter(Boolean).join(' · '))}</small>`:''}`;return btn(content,()=>{if(dragSlot){const from=dragSlot;dragSlot=null;return swapSlots(from,`${d}:${p}`)}dayEditor(d,'시간표',p)},'slot',`style="background:${esc(info.rule?.color||'#FFFFFF')}" draggable="${!!slot}" data-drag="${d}:${p}" data-drop="${d}:${p}"`)}).join('')}
function weekSummary(){const start=C.addDays(date,-((C.weekday(date)+6)%7)),end=C.addDays(start,4);return [...db().events.filter(e=>e.date>=start&&e.date<=end).map(e=>`${e.date.slice(5)} ${e.title}`),...db().timetables.filter(t=>t.date>=start&&t.date<=end&&periodInfo(t).type!=='일반').map(t=>`${t.date.slice(5)} ${t.period}교시 ${t.subjectCode} ${periodInfo(t).type}`)].join(' · ')||'등록된 특이사항 없음'}
function dashboard(){if(dashMode!=='normal')return checkView();const list=students();const completed=list.filter(s=>!isUnfinished(s.id,date)&&!C.excluded(db(),s.id,date)).length;return `<div class="toolbar"><div><h2>${esc(settings().className)}의 하루</h2><small>${esc(date)} · 작은 기록이 모여 성장이 됩니다.</small></div><div class="row"><input aria-label="대시보드 날짜" type="date" value="${date}" id="dash-date">${btn('오늘',()=>{date=C.today();render()})}${btn(compact?'자세히':'컴팩트',()=>{compact=!compact;render()})}${btn('체크',()=>{dashMode='check';checks=new Set(list.map(s=>s.id));render()})}${btn('출결',()=>{dashMode='attendance';render()})}</div></div><section class="panel"><div class="row between"><div class="row"><strong>오늘 일정</strong>${db().events.filter(e=>e.date===date&&e.period==null).map(e=>btn(esc(e.title),()=>dayEditor(date,'일정',null,e),'event')).join('')||'<span class="muted">오늘 일정 없음</span>'}${db().events.filter(e=>e.isDday).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>badge(e.title+' '+C.dday(e.date,date))).join('')}</div>${btn('+ 일정',()=>dayEditor(date))}</div><div class="schedule" style="margin-top:12px">${timeSlots(date)}</div><div class="ticker">이번 주 특이사항 · ${esc(weekSummary())}</div></section><div class="summary"><div class="metric"><small>오늘 함께하는 학생</small><strong>${list.filter(s=>!C.excluded(db(),s.id,date)).length}<small> / ${list.length}명</small></strong></div><div class="metric"><small>할 일을 모두 마친 학생</small><strong>${completed}<small>명</small></strong></div><div class="metric"><small>오늘 남긴 기록</small><strong>${db().records.filter(r=>r.date===date).length}<small>건</small></strong></div></div><div class="toolbar"><strong>우리 반 학생 <span class="muted">${list.length}명</span></strong><small>카드를 눌러 함께 기록 · ⋯ 버튼으로 개별 보기</small></div><section class="${compact?'compact':''}"><div class="students">${list.map(studentCard).join('')}</div></section>${!list.length?empty('아직 등록된 학생이 없습니다.','설정에서 명단을 붙여 넣거나 학생을 추가하세요.'):''}${bindLater('dash-date','change',e=>{date=e.target.value||C.today();render()})}`}
function bindLater(id,event,fn){setTimeout(()=>{const el=document.getElementById(id);if(el)el.addEventListener(event,e=>run(()=>fn(e)))},0);return ''}
function isUnfinished(id,d){if(C.excluded(db(),id,d))return false;return C.pending(db(),id,d).length>0||db().routines.some(r=>!r.deletedAt&&C.targeted(r,id)&&C.routineStatus(db(),r.id,d,id)==='진행중')}
function studentCard(s){const missing=C.pending(db(),s.id,date),ex=C.excluded(db(),s.id,date),score=C.scores(db(),s.id,date,date),routines=db().routines.filter(r=>!r.deletedAt&&C.targeted(r,s.id)),recent=db().records.filter(r=>r.studentIds.includes(s.id)&&r.date<=date).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt))[0];const id=String(++actionNo);actions.set(id,()=>{selected=selected.includes(s.id)?selected.filter(x=>x!==s.id):[...selected,s.id];render()});return `<article role="button" tabindex="0" aria-pressed="${selected.includes(s.id)}" data-action="${id}" class="student ${isUnfinished(s.id,date)?'unfinished':''} ${selected.includes(s.id)?'selected':''} ${ex?'excluded':''}"><div class="student-head"><strong>${esc(s.no)}. ${esc(s.name)}</strong>${btn('⋯',()=>studentDetail(s.id),'','aria-label="'+esc(s.name)+' 상세 보기"')}</div>${ex?badge('제외'):''}<div class="score">★${score.total} <small>${C.AREAS.filter(a=>score.areas[a]).map(a=>esc(a)+score.areas[a]).join(' ')||'기록 없음'}</small></div>${missing.slice(0,2).map(({assignment:a,date:d})=>btn(`${d<date?'이전 · ':''}${esc(a.title)}`,()=>taskStateEditor(a,d,s.id),'task '+(d<date?'overdue':''))).join('')}${routines.slice(0,2).map(r=>btn(`${C.routineStatus(db(),r.id,date,s.id)==='완료'?'☑':C.routineStatus(db(),r.id,date,s.id)==='면제'?'—':'☐'} ${esc(r.title)}`,()=>setRoutine(r,date,s.id,C.routineStatus(db(),r.id,date,s.id)==='완료'?'진행중':'완료'),'task')).join('')}<div class="detail">${esc(recent?.text||'아직 기록이 없습니다.')}</div></article>`}
function checkView(){const list=students(),attendance=dashMode==='attendance',missing=list.filter(s=>!checks.has(s.id)),ex=list.filter(s=>C.excluded(db(),s.id,date));return `<div class="toolbar"><h2>${attendance?'출결 · 제외 표시':'빠른 인원 점검'}</h2><div class="row">${!attendance?btn('전원 체크',()=>{checks=new Set(list.map(s=>s.id));render()})+btn('전원 해제',()=>{checks.clear();render()}):''}${btn('끝내기',()=>{dashMode='normal';render()},'primary')}</div></div><div class="panel"><p>${attendance?'그날 기록·집계에서 제외할 학생을 선택하세요. 표시를 다시 누르면 복귀합니다. 기존 자료는 삭제되지 않습니다.':'임시 점검입니다. 끝내기를 누르면 기록 없이 돌아갑니다.'}</p><strong>${attendance?`총 ${list.length}명 중 ${list.length-ex.length}명 · 제외: ${esc(ex.map(s=>s.name).join(', ')||'없음')}`:`총 ${list.length}명 중 ${checks.size}명 체크 · 미체크: ${esc(missing.map(s=>s.name).join(', ')||'없음')}`}</strong></div><div class="check-mode students">${list.map(s=>{const checked=attendance?C.excluded(db(),s.id,date):checks.has(s.id);return btn(`${checked?'✓ ':''}${esc(s.no)}. ${esc(s.name)}`,async()=>{if(attendance){const row={id:C.stateId('attendance',date,s.id),studentId:s.id,date,excluded:!checked};await commit([up('attendance',row)],'')}else{checked?checks.delete(s.id):checks.add(s.id);render()}},'student '+(attendance?(checked?'excluded':''):(checked?'checked':'')))}).join('')}</div>${!attendance?`<div class="panel" style="margin-top:16px"><label>점검 장소<input id="check-place" placeholder="예: 도서관"></label>${btn('미체크 명단을 관찰 기록으로 남기기',async()=>{if(!missing.length)return toast('미체크 학생이 없습니다.');const place=$('#check-place').value||'인원 점검';await commit(missing.map(s=>up('records',newRecord({studentIds:[s.id],date,kind:'관찰',text:place+' 인원 점검에서 미체크',areas:[]}))));dashMode='normal';render()})}</div>`:''}`}
function newRecord(r){return {id:C.uid(),date:r.date||date,period:'기타',studentIds:[],tagIds:[],areas:[],kind:'관찰',extraType:null,incidentId:null,notified:false,printIncluded:true,text:'',action:'',autoRef:null,createdAt:C.now(),updatedAt:C.now(),...r}}
async function bulkRecord(kind){const ids=selected.filter(id=>!C.excluded(db(),id,date));if(!ids.length)return toast('선택 학생이 모두 제외 상태입니다.');await commit(ids.map(id=>up('records',newRecord({studentIds:[id],kind,date,text:kind==='칭찬'?'칭찬을 남김':kind==='지도'?'조언을 전함':'관찰 기록을 남김'}))));selected=[];render()}
function recordEditor(seed={},existing=false){const r=newRecord(seed);const studentList=db().students.filter(s=>!s.deletedAt||r.studentIds.includes(s.id));const tags=db().tags.filter(t=>!t.deletedAt);const warnings=seed.warnings||[];
 modal(existing?'기록 수정':'기록 확인 후 저장',`${warnings.length?`<div class="notice">${warnings.map(esc).join('<br>')}</div>`:''}${existing?`<p class="muted">최초 작성: ${esc(localTime(r.createdAt))}<br>최근 수정: ${esc(localTime(r.updatedAt))}</p>`:''}${r.autoRef?'<div class="notice">과제 자동 기록입니다. 과제 상태를 통해 수정하면 기록과 상태가 함께 바뀝니다.</div>':''}<div class="formgrid">${input('날짜','date',r.date,'date','required')}${select('교시','period',['아침',...Array.from({length:7},(_,i)=>`${i+1}교시`),'점심','방과후','기타'],r.period)}<div class="span2"><label>학생 · 복수 선택 가능</label>${multiple(studentList.map(s=>[s.id,(s.deletedAt?'(나간 학생) ':'')+s.no+'. '+s.name]),'students',r.studentIds)}</div>${select('구분','kind',C.KINDS.map(k=>[k,kindLabel(k)]),r.kind)}<div><label>경험치 영역</label>${multiple(C.AREAS.map(a=>[a,a]),'areas',r.areas)}</div><div class="span2"><label>태그</label>${multiple(tags.map(t=>[t.id,t.label]),'tags',r.tagIds)}</div><div class="span2">${textarea('내용 · 입력 원문을 보존합니다.','text',r.text)}</div><div class="span2">${textarea('조치 · 필요하면 내용과 나누어 수정하세요.','action',r.action)}</div><div class="span2" id="extra-panel">${select('추가 기록 유형','extraType',['메모','사건','상담'],r.extraType||'메모')}${input('새 사건 제목 · 사건 유형에서 새 사안을 만들 때','incidentTitle',r.kind==='추가기록'&&r.extraType==='사건'?r.text.slice(0,40):'')}${select('기존 사건 연결','incidentId',[['','연결하지 않음'],...db().incidents.map(i=>[i.id,i.title+' ('+i.status+')'])],r.incidentId||'')}<div id="counsel-panel" class="panel" style="margin-top:12px">${select('상담 방식','method',['전화','대면','문자·기타'],r.counseling?.method||'대면')}<div class="row" style="margin-top:12px">${checkbox('학생 참석','studentAttendee',r.counseling?.attendees?.student)}${checkbox('보호자 참석/통화','guardian',r.counseling?.attendees?.guardian)}${checkbox('추가 참석자','additional',r.counseling?.attendees?.additional)}</div><div id="guardian-info">${input('보호자 정보','guardianInfo',r.counseling?.attendees?.guardianInfo||'')}</div><div id="additional-info">${input('추가 참석자 정보','additionalInfo',r.counseling?.attendees?.additionalInfo||'')}</div></div><div class="row" style="margin-top:12px">${checkbox('가정 통보했음','notified',r.notified)}${checkbox('가정 발송 보고서에 인쇄 포함','printIncluded',r.kind==='추가기록'?r.printIncluded:false)}</div></div></div>`,async f=>{
 const ids=f.getAll('students');if(!ids.length)throw Error('학생을 1명 이상 선택하세요.');if(!f.get('text').trim())throw Error('기록 내용을 입력하세요.');if(existing&&r.autoRef)throw Error('자동 기록은 해당 과제의 상태에서 변경하세요.');const recordDate=f.get('date');const skipped=ids.filter(id=>C.excluded(db(),id,recordDate));if(skipped.length)throw Error('출결 제외 학생은 기록 대상에서 해제해 주세요: '+skipped.map(name).join(', '));let incidentId=f.get('incidentId')||null;const kind=f.get('kind'),extra=kind==='추가기록';let ops=[];
 if(extra&&f.get('extraType')==='사건'&&!incidentId){const title=f.get('incidentTitle').trim();if(!title)throw Error('사건 제목을 입력하세요.');incidentId=C.uid();ops.push(up('incidents',{id:incidentId,title,date:recordDate,studentIds:ids,status:'진행중',description:f.get('text'),linkedIds:[],createdAt:C.now(),updatedAt:C.now()}))}
 if(incidentId){const old=db().incidents.find(i=>i.id===incidentId);if(old)ops.push(up('incidents',{...old,studentIds:[...new Set([...old.studentIds,...ids])],updatedAt:C.now()}))}
 const values={...r,date:recordDate,period:f.get('period'),kind,text:f.get('text').trim(),action:f.get('action').trim(),areas:f.getAll('areas'),tagIds:f.getAll('tags'),extraType:extra?f.get('extraType'):null,incidentId,notified:!!f.get('notified'),printIncluded:extra?!!f.get('printIncluded'):true,counseling:extra&&f.get('extraType')==='상담'?{method:f.get('method'),attendees:{student:!!f.get('studentAttendee'),guardian:!!f.get('guardian'),guardianInfo:f.get('guardian')?f.get('guardianInfo'):null,additional:!!f.get('additional'),additionalInfo:f.get('additional')?f.get('additionalInfo'):null}}:null,updatedAt:C.now()};delete values.warnings;
 if(existing)ops.push(up('records',{...values,studentIds:ids}));else for(const id of ids)ops.push(up('records',{...values,id:C.uid(),studentIds:[id]}));await commit(ops);selected=[];closeModal();render();
 });const form=$('#modal-form');const update=()=>{const extra=form.elements.kind.value==='추가기록';$('#extra-panel').hidden=!extra;$('#counsel-panel').hidden=form.elements.extraType.value!=='상담';$('#guardian-info').hidden=!form.elements.guardian.checked;$('#additional-info').hidden=!form.elements.additional.checked};form.elements.printIncluded.onchange=e=>{if(e.target.checked&&!confirm('이 내용은 학부모에게 전달되는 보고서에 인쇄됩니다. 전달 가능한 내용인지 다시 한번 확인하셨나요?'))e.target.checked=false};form.onchange=e=>{if(e.target.name==='tags'){const checked=[...form.querySelectorAll('[name=tags]:checked')].map(x=>x.value);const areas=new Set(tags.filter(t=>checked.includes(t.id)).map(t=>t.area));form.querySelectorAll('[name=areas]').forEach(el=>{if(areas.has(el.value))el.checked=true})}update()};update();form.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&e.target.tagName!=='TEXTAREA'&&e.target.tagName!=='BUTTON'){e.preventDefault();form.requestSubmit()}}}
function localTime(s){return new Date(s).toLocaleString('sv-SE',{timeZone:'Asia/Seoul'})}
function recordCard(r,controls=true){return `<article class="record ${r.kind==='칭찬'?'praise':r.kind==='지도'?'advice':''}"><div class="row between"><div class="row"><strong>${esc(r.studentIds.map(name).join(', '))}</strong>${badge(kindLabel(r.kind))}${r.extraType?badge(r.extraType):''}<small>${esc(r.date)} ${esc(r.period)}</small>${r.autoRef?badge('자동'):''}${r.kind==='추가기록'?badge(r.printIncluded?'인쇄 포함':'비공개'):''}${r.notified?badge('가정 통보'):''}</div>${controls?`<div class="row">${r.incidentId?btn('사건 보기',()=>incidentDetail(r.incidentId)):''}${r.autoRef?btn('과제 상태',()=>{const state=db().assignmentStates.find(s=>s.id===r.autoRef),a=db().assignments.find(a=>a.id===state?.assignmentId);if(a)taskStateEditor(a,state.date,state.studentId)}):btn('수정',()=>recordEditor(r,true))}${btn('삭제',async()=>{if(r.autoRef){if(!confirm('자동 기록을 삭제하면 연결된 과제를 진행중으로 되돌립니다. 계속할까요?'))return;const state=db().assignmentStates.find(s=>s.id===r.autoRef),a=db().assignments.find(a=>a.id===state?.assignmentId);if(a)await commit(C.taskStateOps(db(),a,state.date,state.studentId,'진행중'));else await commit([{table:'records',id:r.id,remove:true}]);}else if(confirm('이 기록을 삭제할까요?'))await commit([{table:'records',id:r.id,remove:true}]);},'danger')}</div>`:''}</div><div class="body">${esc(r.text)}</div>${r.action?`<div class="action">조치 · ${esc(r.action)}</div>`:''}<div class="chips" style="margin-top:8px">${(r.areas||[]).map(badge).join('')}${(r.tagIds||[]).map(id=>badge(db().tags.find(t=>t.id===id&&!t.deletedAt)?.label||'(삭제된 항목)')).join('')}</div></article>`}
function recordsView(){const f=recordFilters,list=db().records.filter(r=>r.date>=f.from&&r.date<=f.to&&(!f.student||r.studentIds.includes(f.student))&&(!f.kind||r.kind===f.kind)&&(!f.tag||r.tagIds.includes(f.tag))&&(!f.area||r.areas.includes(f.area))&&(!f.q||[r.text,r.action].join(' ').includes(f.q))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));return `<div class="toolbar"><div><h2>기록</h2><small>사실을 남기고, 변화의 흐름을 살펴보세요.</small></div><div class="row">${btn('오늘',()=>{recordFilters.from=recordFilters.to=C.today();render()})}${btn('이번 달',()=>{recordFilters.from=date.slice(0,7)+'-01';recordFilters.to=date;render()})}${btn('사건 목록',incidentList)}${btn('+ 기록',()=>recordEditor({date}),'primary')}</div></div><form id="record-filter" class="filters">${input('시작','from',f.from,'date')}${input('종료','to',f.to,'date')}${select('학생','student',[['','전체'],...db().students.map(s=>[s.id,name(s.id)])],f.student)}${select('구분','kind',[['','전체'],...C.KINDS.map(k=>[k,kindLabel(k)])],f.kind)}${select('영역','area',[['','전체'],...C.AREAS],f.area)}${select('태그','tag',[['','전체'],...db().tags.map(t=>[t.id,t.label])],f.tag)}${input('내용 검색','q',f.q)}<button class="primary">조회</button></form><p class="muted">${list.length}건 · 제외일의 기록은 보존되며 점수 집계에서만 제외됩니다.</p>${list.map(r=>recordCard(r)).join('')||empty('조건에 맞는 기록이 없습니다.','기간이나 필터를 바꾸어 보세요.')}${bindLater('record-filter','submit',e=>{e.preventDefault();recordFilters=Object.fromEntries(new FormData(e.target));render()})}`}
function incidentList(){modal('사건 목록',`${btn('+ 사건 기록',()=>recordEditor({kind:'추가기록',extraType:'사건',printIncluded:false,studentIds:selected}))}${db().incidents.map(i=>`<div class="record"><div class="row between"><div><strong>${esc(i.title)}</strong> ${badge(i.status)}<div class="muted">${esc(i.date)} · ${esc(i.studentIds.map(name).join(', '))}</div></div>${btn('타임라인',()=>incidentDetail(i.id))}</div></div>`).join('')||empty('등록된 사건이 없습니다.')}`)}
function incidentDetail(id){const incident=db().incidents.find(i=>i.id===id);if(!incident)return toast('사건을 찾지 못했습니다.');const linked=C.linkedIncidentIds(db(),id),records=db().records.filter(r=>linked.has(r.incidentId)).sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt));modal(incident.title,`<div class="row">${badge(incident.status)}${btn(incident.status==='진행중'?'종결 처리':'진행중으로',async()=>{await commit([up('incidents',{...incident,status:incident.status==='진행중'?'종결':'진행중',updatedAt:C.now()})]);incidentDetail(id)})}${btn('+ 후속 기록',()=>recordEditor({studentIds:incident.studentIds,kind:'추가기록',extraType:'메모',incidentId:id,printIncluded:false}))}${btn('기록 연결',()=>linkRecords(id))}${btn('사건 연결',()=>linkIncidents(id))}</div><div class="panel" style="margin-top:12px"><small>${esc(incident.date)} · ${esc(incident.studentIds.map(name).join(', '))}</small><p style="white-space:pre-wrap">${esc(incident.description)}</p></div>${[...linked].filter(x=>x!==id).map(x=>{const i=db().incidents.find(v=>v.id===x);return i?badge('연결: '+i.title):''}).join('')}${records.map(r=>`<small>${esc(db().incidents.find(i=>i.id===r.incidentId)?.title)}</small>${recordCard(r)}`).join('')}`)}
function linkRecords(id){const list=[...db().records].sort((a,b)=>b.date.localeCompare(a.date));modal('과거 기록 연결',`<p class="muted">체크한 기록을 이 사건에 연결합니다. 다른 사건에 속한 기록은 이동됩니다.</p><input id="link-search" placeholder="기록 내용·학생 검색" aria-label="연결할 기록 검색" style="width:100%;margin-bottom:12px">${list.map(r=>`<label class="record inline" data-search="${esc(r.text+' '+r.studentIds.map(name).join(' '))}"><input type="checkbox" name="records" value="${esc(r.id)}" ${r.incidentId===id?'checked':''}><span>${esc(r.date)} · ${esc(r.studentIds.map(name).join(', '))}<br>${esc(r.text)}</span></label>`).join('')}`,async f=>{const chosen=new Set(f.getAll('records'));const ops=list.filter(r=>chosen.has(r.id)||r.incidentId===id).map(r=>up('records',{...r,incidentId:chosen.has(r.id)?id:null,updatedAt:C.now()}));await commit(ops);incidentDetail(id)});$('#link-search').oninput=e=>document.querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.includes(e.target.value))}
function linkIncidents(id){const incident=db().incidents.find(i=>i.id===id),list=db().incidents.filter(i=>i.id!==id);modal('사건 연결 · 병합하지 않고 연결합니다.',multiple(list.map(i=>[i.id,i.date+' '+i.title]),'linked',incident.linkedIds||[]),async f=>{const chosen=f.getAll('linked');const ops=[up('incidents',{...incident,linkedIds:chosen,updatedAt:C.now()})];for(const i of list){let links=(i.linkedIds||[]).filter(x=>x!==id);if(chosen.includes(i.id))links.push(id);ops.push(up('incidents',{...i,linkedIds:links,updatedAt:C.now()}))}await commit(ops);incidentDetail(id)})}
function targetForm(target='all'){return `<div class="span2">${select('대상','target',[['all','전체 학생'],['some','선택 학생']],target==='all'?'all':'some')}<div id="target-students" style="margin-top:9px">${multiple(students().map(s=>[s.id,name(s.id)]),'students',target?.studentIds||[])}</div></div>`}
function setupTarget(){const form=$('#modal-form');const update=()=>$('#target-students').hidden=form.elements.target.value==='all';form.elements.target.onchange=update;update()}
function getTarget(f){if(f.get('target')==='all')return 'all';const ids=f.getAll('students');if(!ids.length)throw Error('대상 학생을 선택하세요.');return {studentIds:ids}}
function assignmentEditor(a=null,d=date){const r=a||{id:C.uid(),title:'',date:d,repeat:{type:'none',weekdays:[]},target:'all',statArea:'과제',createdAt:C.now()};modal(a?'과제 수정':'새 과제',`<div class="formgrid">${input('과제 제목','title',r.title,'text','required')}${input('시작일 / 마감일','date',r.date,'date','required')}${select('반복','repeat',[['none','없음'],['daily','매일'],['weekly','매주 요일 지정']],r.repeat.type)}${select('경험치 영역','statArea',[['','미지정'],...C.AREAS],r.statArea||'')}<div class="span2" id="repeat-days"><label>반복 요일</label>${multiple([[1,'월'],[2,'화'],[3,'수'],[4,'목'],[5,'금'],[6,'토'],[0,'일']].map(([x,y])=>[String(x),y]),'weekdays',(r.repeat.weekdays||[]).map(String))}</div>${targetForm(r.target)}</div>`,async f=>{const repeat={type:f.get('repeat')};if(repeat.type==='weekly'){repeat.weekdays=f.getAll('weekdays').map(Number);if(!repeat.weekdays.length)throw Error('요일을 선택하세요.')}const next={...r,title:f.get('title').trim(),date:f.get('date'),repeat,target:getTarget(f),statArea:f.get('statArea')||null};if(!next.title)throw Error('제목을 입력하세요.');await commit([up('assignments',next)]);closeModal()});setupTarget();const repeat=$('#modal-form').elements.repeat;const update=()=>$('#repeat-days').hidden=repeat.value!=='weekly';repeat.onchange=update;update()}
function assignmentsView(){const assignments=db().assignments.filter(a=>!a.deletedAt),daily=assignments.filter(a=>C.occurs(a,date));return `<div class="toolbar"><div><h2>과제</h2><small>과제 × 날짜 × 학생마다 상태가 독립적으로 저장됩니다.</small></div><div class="row"><input id="assignment-date" aria-label="과제 날짜" type="date" value="${date}">${btn('+ 과제',()=>assignmentEditor(),'primary')}</div></div><section class="panel"><h3>${esc(date)} 과제 상태</h3>${daily.length?`<div class="table-wrap"><table><thead><tr><th>학생</th>${daily.map(a=>`<th>${esc(a.title)}</th>`).join('')}</tr></thead><tbody>${students().map(s=>`<tr><th>${esc(name(s.id))}${C.excluded(db(),s.id,date)?badge('제외'):''}</th>${daily.map(a=>{const state=db().assignmentStates.find(x=>x.id===C.stateId(a.id,date,s.id));return `<td>${C.targeted(a,s.id)?btn(esc(state?.status||'진행중'),()=>taskStateEditor(a,date,s.id),state?.status==='안함'?'danger':'')+`<div class="muted">${esc(state?.memo||'')}</div>`:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:empty('이 날짜에 등록된 과제가 없습니다.','새 과제를 등록하거나 날짜를 바꾸세요.')}</section><section class="panel"><h3>등록한 과제</h3>${assignments.map(a=>`<div class="record"><div class="row between"><div><strong>${esc(a.title)}</strong> ${badge(a.repeat.type==='none'?'1회':a.repeat.type==='daily'?'매일':'매주 '+a.repeat.weekdays.map(n=>'일월화수목금토'[n]).join('·'))}<div class="muted">${esc(a.date)}${a.endDate?' ~ '+esc(a.endDate):''} · ${a.target==='all'?'전체 학생':esc(a.target.studentIds.map(name).join(', '))} · ${esc(a.statArea||'영역 미지정')}</div></div><div class="row">${btn('수정',()=>assignmentEditor(a))}${btn('복사',()=>assignmentEditor({...a,id:C.uid(),createdAt:C.now(),date,deletedAt:null,endDate:null}))}${btn('삭제/중단',()=>deleteAssignment(a),'danger')}</div></div></div>`).join('')||empty('등록한 과제가 없습니다.')}</section>${bindLater('assignment-date','change',e=>{date=e.target.value||C.today();render()})}`}
function taskStateEditor(a,d,s){const current=db().assignmentStates.find(x=>x.id===C.stateId(a.id,d,s));modal(`${name(s)} · ${a.title}`,`<p class="muted">${esc(d)}의 과제 · 완료/늦게완료 +1 · 안함 −1 · 진행중/면제 0</p>${C.excluded(db(),s,d)?'<div class="notice">출결 제외일입니다. 상태는 보존되며 점수 집계에서는 제외됩니다.</div>':''}${select('상태','status',C.STATUSES,current?.status||'진행중')}${input('상태 메모 · 선택','memo',current?.memo||'')}`,async f=>{await commit(C.taskStateOps(db(),a,d,s,f.get('status'),f.get('memo').trim()));closeModal()})}
function deleteAssignment(a){modal('과제 삭제 / 반복 중단',`<p>${esc(a.title)}</p>${select('처리 방식','mode',[['future',date+'부터 앞으로만 중단 · 이전 상태/기록 보존'],['all','과제와 모든 상태·자동 기록을 삭제']],'future')}`,async f=>{if(!confirm('선택한 방식으로 처리할까요?'))return;const all=f.get('mode')==='all';const cutoff=date;let ops=[];const states=db().assignmentStates.filter(s=>s.assignmentId===a.id&&(all||s.date>=cutoff));ops.push(all?{table:'assignments',id:a.id,remove:true}:up('assignments',{...a,endDate:C.addDays(cutoff,-1)}));for(const state of states){ops.push({table:'assignmentStates',id:state.id,remove:true});for(const r of db().records.filter(r=>r.autoRef===state.id))ops.push({table:'records',id:r.id,remove:true})}await commit(ops);closeModal()})}
function routineEditor(r=null){const row=r||{id:C.uid(),title:'',target:'all',sortOrder:db().routines.length,createdAt:C.now()};modal(r?'루틴 수정':'새 루틴',`<div class="formgrid">${input('루틴 제목','title',row.title,'text','required')}${input('정렬 순서','sortOrder',row.sortOrder,'number')}${targetForm(row.target)}</div>`,async f=>{await commit([up('routines',{...row,title:f.get('title').trim(),sortOrder:Number(f.get('sortOrder')),target:getTarget(f)})]);closeModal()});setupTarget()}
async function setRoutine(r,d,s,status){const row={id:C.stateId(r.id,d,s),routineId:r.id,date:d,studentId:s,status,updatedAt:C.now()};await commit([up('routineStates',row)],'')}
function routinesView(){const routines=db().routines.filter(r=>!r.deletedAt).sort((a,b)=>a.sortOrder-b.sortOrder);return `<div class="toolbar"><div><h2>루틴</h2><small>날짜가 바뀌면 새 체크로 시작합니다. 루틴 체크에는 별 점수를 부여하지 않습니다.</small></div><div class="row"><input aria-label="루틴 날짜" type="date" id="routine-date" value="${date}">${btn('+ 루틴',()=>routineEditor(),'primary')}</div></div>${routines.map(r=>`<section class="panel"><div class="toolbar"><h3>${esc(r.title)}</h3><div class="row">${['진행중','완료','면제'].map(status=>btn(status==='진행중'?'전체 리셋':'전체 '+status,async()=>{if(!confirm(`${r.title}: ${date} 대상 학생 전체를 ${status}으로 바꿀까요?`))return;const ops=students().filter(s=>C.targeted(r,s.id)&&!C.excluded(db(),s.id,date)).map(s=>up('routineStates',{id:C.stateId(r.id,date,s.id),routineId:r.id,date,studentId:s.id,status,updatedAt:C.now()}));await commit(ops)})).join('')}${btn('수정',()=>routineEditor(r))}${btn('삭제',async()=>{if(confirm('루틴을 삭제할까요? 기존 체크 이력은 보존합니다.'))await commit([up('routines',{...r,deletedAt:C.now()})])},'danger')}</div></div><div class="checkgrid">${students().filter(s=>C.targeted(r,s.id)).map(s=>{const status=C.routineStatus(db(),r.id,date,s.id);return btn(`${status==='완료'?'☑':status==='면제'?'—':'☐'} ${esc(name(s.id))}`,()=>{modal(r.title+' · '+name(s.id),select('상태','status',['진행중','완료','면제'],status),async f=>{await setRoutine(r,date,s.id,f.get('status'));closeModal()})},status==='진행중'?'':'primary')}).join('')}</div></section>`).join('')||empty('매일 확인할 루틴을 등록하세요.','연산, 독서, 일기장 제출 등 학급에 맞게 자유롭게 만들 수 있습니다.')}${bindLater('routine-date','change',e=>{date=e.target.value||C.today();render()})}`}
function calendarView(){const first=calendarDate.slice(0,7)+'-01',start=calendarMode==='month'?C.addDays(first,-C.weekday(first)):C.addDays(calendarDate,-((C.weekday(calendarDate)+6)%7)),days=calendarMode==='month'?42:5;const heads=calendarMode==='month'?['일','월','화','수','목','금','토']:['월','화','수','목','금'];return `<div class="toolbar"><div><h2>시간표·일정</h2><small>종일 일정 · 교시별 수업과 행사 · 마감 과제</small></div><div class="row">${btn('‹',()=>{if(calendarMode==='week')calendarDate=C.addDays(calendarDate,-7);else{const dt=new Date(first+'T12:00Z');dt.setUTCMonth(dt.getUTCMonth()-1);calendarDate=dt.toISOString().slice(0,10)}render()})}<strong>${esc(calendarMode==='month'?calendarDate.slice(0,7):start+' 주간')}</strong>${btn('›',()=>{if(calendarMode==='week')calendarDate=C.addDays(calendarDate,7);else{const dt=new Date(first+'T12:00Z');dt.setUTCMonth(dt.getUTCMonth()+1);calendarDate=dt.toISOString().slice(0,10)}render()})}${btn('오늘',()=>{calendarDate=C.today();render()})}${btn(calendarMode==='month'?'주간 보기':'월간 보기',()=>{calendarMode=calendarMode==='month'?'week':'month';render()})}${btn('기본안 일괄 배포',bulkTimetable)}${btn('시수 계산',hoursDialog)}</div></div><div class="row" style="margin-bottom:14px">${[['events','종일 일정'],['time','시간표'],['tasks','과제'],['detail','자세히 보기']].map(([key,label])=>btn((calendarFilters[key]?'✓ ':'')+label,()=>{calendarFilters[key]=!calendarFilters[key];render()},calendarFilters[key]?'primary':'')).join('')}<small>수업을 드래그해 교체 · 터치는 길게 누른 후 대상 교시 선택</small></div><div class="table-wrap"><div class="calendar ${calendarMode==='week'?'week':''}">${heads.map(h=>`<div class="weekday">${h}</div>`).join('')}${Array.from({length:days},(_,i)=>{const d=C.addDays(start,i),events=db().events.filter(e=>e.date===d&&e.period==null),tasks=db().assignments.filter(a=>C.occurs(a,d));return `<div class="day ${d.slice(0,7)!==calendarDate.slice(0,7)?'faded':''} ${d===C.today()?'today':''}">${btn(`<span>${Number(d.slice(-2))}${calendarMode==='week'?'일':''}</span><small>＋</small>`,()=>dayEditor(d),'day-head')}${calendarFilters.events?events.map(e=>btn(esc(e.title)+(e.isDday?' '+badge(C.dday(e.date)):''),()=>dayEditor(d,'일정',null,e),'event')).join(''):''}${calendarFilters.time?timeSlots(d,true):''}${calendarFilters.tasks?tasks.map(a=>{const targets=students().filter(s=>C.targeted(a,s.id)&&!C.excluded(db(),s.id,d)),done=targets.filter(s=>['완료','늦게완료','면제'].includes(C.assignmentStatus(db(),a.id,d,s.id))).length;return `<div class="taskline">${btn(esc(a.title)+` <small>${done}/${targets.length}</small>`,()=>{date=d;tab='과제';render()},'task')}</div>`}).join(''):''}</div>`}).join('')}</div></div>`}
function dayEditor(d,mode='일정',period=1,event=null){if(mode==='과제'){closeModal();assignmentEditor(null,d);return}const slot=db().timetables.find(t=>t.date===d&&t.period===(period||1));const r=event||{id:C.uid(),date:d,period:null,title:'',description:'',isDday:false,createdAt:C.now()};modal(d+' · 통합 등록',`<div class="row" style="margin-bottom:18px">${['일정','시간표','과제'].map(t=>btn(t,()=>dayEditor(d,t,period),mode===t?'primary':'')).join('')}</div>${mode==='일정'?`<div class="formgrid">${input('일정 이름','title',r.title,'text','required')}${select('시간','period',[['','종일'],[0,'아침'],...[1,2,3,4,5,6].map(p=>[p,p+'교시']),[7,'방과후']],r.period??'')}<div class="span2">${textarea('설명','description',r.description)}</div>${checkbox('D-Day 표시','isDday',r.isDday)}</div>${event?btn('이 일정 삭제',async()=>{if(confirm('일정을 삭제할까요?')){await commit([{table:'events',id:r.id,remove:true}]);closeModal()}},'danger'):''}`:`<div class="subject-grid">${db().subject_rules.sort((a,b)=>a.sortOrder-b.sortOrder).map(s=>btn(esc(s.code),async()=>{const p=Number($('#modal-form').elements.period.value),old=db().timetables.find(t=>t.date===d&&t.period===p);await commit([up('timetables',{id:`${d}-${p}`,date:d,period:p,subjectCode:s.code,memo:$('#modal-form').elements.memo.value,type:s.defaultType,locationOverride:null,teacherOverride:null,updatedAt:C.now()})]);dayEditor(d,'시간표',p)},'',`style="background:${esc(s.color)}"`)).join('')}</div><p class="muted" style="margin:8px 0">과목 버튼을 누르면 바로 저장됩니다. 아래에서 세부 내용까지 입력할 수도 있습니다.</p><div class="formgrid">${select('교시','period',[[0,'아침'],...[1,2,3,4,5,6].map(p=>[p,p+'교시']),[7,'방과후']],period||1)}${select('과목','subjectCode',db().subject_rules.map(s=>s.code),slot?.subjectCode||db().subject_rules[0]?.code)}${select('특이사항','type',['일반','외부','강사','다른장소'],slot?.type||'일반')}${input('수업 메모','memo',slot?.memo||'')}${input('이날만 장소 변경','locationOverride',slot?.locationOverride||'')}${input('이날만 담당 교사 변경','teacherOverride',slot?.teacherOverride||'')}</div>${btn('이 교시 비우기',async()=>{const p=Number($('#modal-form').elements.period.value);if(confirm('선택한 교시를 비울까요?')){await commit([{table:'timetables',id:`${d}-${p}`,remove:true}]);closeModal()}},'danger')}`}`,async f=>{if(mode==='일정'){await commit([up('events',{...r,title:f.get('title').trim(),period:f.get('period')===''?null:Number(f.get('period')),description:f.get('description'),isDday:!!f.get('isDday')})])}else{const p=Number(f.get('period'));await commit([up('timetables',{id:`${d}-${p}`,date:d,period:p,subjectCode:f.get('subjectCode'),type:f.get('type'),memo:f.get('memo'),locationOverride:f.get('locationOverride')||null,teacherOverride:f.get('teacherOverride')||null,updatedAt:C.now()})])}closeModal()});if(mode==='시간표')$('#modal-form').elements.period.onchange=e=>dayEditor(d,'시간표',Number(e.target.value))}
async function swapSlots(from,to){if(from===to)return;const unpack=x=>{const [d,p]=x.split(':');return {d,p:Number(p)}};const a=unpack(from),b=unpack(to),one=db().timetables.find(t=>t.date===a.d&&t.period===a.p),two=db().timetables.find(t=>t.date===b.d&&t.period===b.p);if(!one)return;const ops=[up('timetables',{...one,id:`${b.d}-${b.p}`,date:b.d,period:b.p,updatedAt:C.now()})];if(two)ops.push(up('timetables',{...two,id:`${a.d}-${a.p}`,date:a.d,period:a.p,updatedAt:C.now()}));else ops.push({table:'timetables',id:one.id,remove:true});await commit(ops,'시간표를 교체했습니다.')}
function bulkTimetable(){const template=settings().weeklyTemplate||{};modal('주간 기본안 · 기간 일괄 배포',`<p class="muted">기본안을 저장한 뒤 선택 기간의 월~금 시간표에 배포합니다. 이미 입력된 시간표는 기본적으로 보존합니다.</p><div class="table-wrap"><table><thead><tr><th>교시</th>${['월','화','수','목','금'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${[1,2,3,4,5,6].map(p=>`<tr><th>${p}</th>${[1,2,3,4,5].map(w=>`<td><select name="slot-${w}-${p}" aria-label="${w}요일 ${p}교시">${opts([['','없음'],...db().subject_rules.map(s=>s.code)],template[`${w}-${p}`]||'')}</select></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="formgrid" style="margin-top:14px">${input('배포 시작일','from',date,'date','required')}${input('배포 종료일','to',C.addDays(date,30),'date','required')}${checkbox('기존 시간표도 덮어쓰기','overwrite')}${checkbox('기본안만 저장 · 배포하지 않음','templateOnly')}</div>`,async f=>{const tmpl={};for(const [k,v] of f)if(k.startsWith('slot-'))tmpl[k.slice(5)]=v;const ops=[up('settings',{...settings(),weeklyTemplate:tmpl})];if(!f.get('templateOnly')){const range=C.dates(f.get('from'),f.get('to'));if(range.length>370)throw Error('한 번에 1년 이내로 배포하세요.');for(const d of range){const w=C.weekday(d);if(w<1||w>5)continue;for(let p=1;p<=6;p++){const code=tmpl[`${w}-${p}`],id=`${d}-${p}`,old=db().timetables.find(t=>t.id===id);if(old&&!f.get('overwrite'))continue;if(code){const rule=db().subject_rules.find(s=>s.code===code);ops.push(up('timetables',{id,date:d,period:p,subjectCode:code,type:rule.defaultType,memo:'',locationOverride:null,teacherOverride:null,updatedAt:C.now()}))}else if(old&&f.get('overwrite'))ops.push({table:'timetables',id,remove:true})}}if(!confirm(`${ops.length-1}개 수업 변경을 저장할까요?`))return}await commit(ops);closeModal()})}
function hoursDialog(from=calendarDate.slice(0,7)+'-01',to=new Date(Date.UTC(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7)),0)).toISOString().slice(0,10)){const rows=db().subject_rules.map(s=>[s.code,db().timetables.filter(t=>t.date>=from&&t.date<=to&&t.subjectCode===s.code).length]);modal('과목별 수업 시수',`<div class="formgrid">${input('시작','from',from,'date')}${input('종료','to',to,'date')}</div><p class="muted" style="margin:12px 0">저장된 실제 시간표의 과목 슬롯을 합산합니다. 교시 연계 행사는 수업 슬롯 자체를 바꾸지 않으므로, 수업을 대체한 경우 해당 슬롯도 변경해 주세요.</p><table><thead><tr><th>과목</th><th>차시</th></tr></thead><tbody>${rows.map(([s,n])=>`<tr><td>${esc(s)}</td><td>${n}</td></tr>`).join('')}</tbody></table>`,async f=>hoursDialog(f.get('from'),f.get('to')),'다시 계산')}
function studentsView(){const first=date.slice(0,7)+'-01';return `<div class="toolbar"><div><h2>학생</h2><small>이번 달 기록과 아직 남은 일을 살펴보세요.</small></div>${btn('+ 학생',()=>studentEditor(),'primary')}</div><div class="table-wrap"><table><thead><tr><th>학생</th><th>모둠</th><th>이번 달 칭찬 / 조언</th><th>미완료 과제</th><th>최근 기록일</th><th>바로 기록</th></tr></thead><tbody>${students().map(s=>{const records=C.scores(db(),s.id,first,date).records;return `<tr><td>${btn(esc(name(s.id)),()=>studentDetail(s.id))}</td><td>${esc(s.group)}</td><td>${records.filter(r=>r.kind==='칭찬').length} / ${records.filter(r=>r.kind==='지도').length}</td><td>${C.pending(db(),s.id,date).length}</td><td>${esc(db().records.filter(r=>r.studentIds.includes(s.id)).map(r=>r.date).sort().at(-1)||'—')}</td><td>${btn('+ 기록',()=>recordEditor({studentIds:[s.id],date}))}</td></tr>`}).join('')}</tbody></table></div>${!students().length?empty('등록된 학생이 없습니다.','학생을 추가하거나 설정에서 명단을 붙여 넣으세요.'):''}`}
function studentDetail(id,from=date.slice(0,7)+'-01',to=date){const s=db().students.find(s=>s.id===id);if(!s)return;const score=C.scores(db(),id,from,to),records=db().records.filter(r=>r.studentIds.includes(id)&&r.date>=from&&r.date<=to).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)),pending=C.pending(db(),id,date);modal(name(id),`<div class="row" style="margin-bottom:14px">${btn('+ 기록',()=>recordEditor({studentIds:[id],date}))}${btn('학생 수정',()=>studentEditor(s))}${btn('보고서로 내보내기',()=>reportDialog(id,from,to),'primary')}${btn('이번 주',()=>studentDetail(id,C.addDays(date,-((C.weekday(date)+6)%7)),date))}${btn('이번 달',()=>studentDetail(id,date.slice(0,7)+'-01',date))}</div><div class="row"><input aria-label="기록 조회 시작" type="date" id="student-from" value="${from}"><span>~</span><input aria-label="기록 조회 종료" type="date" id="student-to" value="${to}">${btn('조회',()=>studentDetail(id,$('#student-from').value,$('#student-to').value))}</div><div class="panel" style="margin-top:14px"><h3>★ ${score.total} · 기간 요약</h3><div class="chips">${C.AREAS.map(a=>badge(a+' '+score.areas[a])).join('')}</div><p class="muted" style="margin-top:10px">${db().tags.map(t=>{const n=records.filter(r=>r.tagIds.includes(t.id)).length;return n?esc(t.label)+' '+n+'회':''}).filter(Boolean).join(' · ')||'태그 기록 없음'}</p></div><h3>미완료 과제 ${pending.length}건</h3>${pending.map(({assignment:a,date:d})=>btn(esc(d+' '+a.title),()=>taskStateEditor(a,d,id))).join('')||'<p class="muted">남은 과제가 없습니다.</p>'}<details style="margin-top:14px"><summary>과제 처리 이력</summary>${db().assignmentStates.filter(x=>x.studentId===id&&x.date>=from&&x.date<=to).map(x=>`<p>${esc(x.date)} · ${esc(db().assignments.find(a=>a.id===x.assignmentId)?.title||'(삭제된 과제)')} · ${esc(x.status)} ${esc(x.memo)}</p>`).join('')||'<p>처리 이력 없음</p>'}</details><details><summary>출결 제외 이력</summary><p>${db().attendance.filter(x=>x.studentId===id&&x.excluded).map(x=>esc(x.date)).sort().join(' · ')||'없음'}</p></details><h3 style="margin-top:20px">기록 ${records.length}건</h3>${records.map(r=>recordCard(r)).join('')||empty('조회 기간에 기록이 없습니다.')}`)}
function studentEditor(s=null){const row=s||{id:C.uid(),no:Math.max(0,...students().map(s=>s.no))+1,name:'',group:'',seat:null,academicYear:settings().academicYear,studentCode:'',createdAt:C.now()};modal(s?'학생 수정':'학생 추가',`<div class="formgrid">${input('번호','no',row.no,'number','min="1" required')}${input('이름','name',row.name,'text','required')}${input('모둠','group',row.group)}${input('교실 화면 별칭','alias',row.alias||'')}</div>`,async f=>{const next={...row,no:Number(f.get('no')),name:f.get('name').trim(),group:f.get('group'),alias:f.get('alias'),deletedAt:null};if(!next.name||!Number.isInteger(next.no)||next.no<1)throw Error('번호와 이름을 확인하세요.');const duplicate=students().filter(x=>x.id!==row.id&&x.no===next.no);if(duplicate.length&&!confirm('같은 번호 학생이 있습니다. 그대로 저장할까요?'))return;if(!s){const removed=db().students.find(x=>x.deletedAt&&x.no===next.no&&x.name===next.name);if(removed&&confirm('같은 번호·이름의 나간 학생이 있습니다. 기존 기록과 다시 연결할까요?')){next.id=removed.id;next.createdAt=removed.createdAt;next.seat=null}}await commit([up('students',next)]);closeModal()})}
function reportDialog(id,from,to){const s=db().students.find(x=>x.id===id);modal('개별 보고서 · 기간 선택',`<p>${esc(name(id))}</p><div class="formgrid">${input('시작일','from',from,'date','required')}${input('종료일','to',to,'date','required')}</div><p class="muted">추가 기록은 인쇄 포함을 승인한 건만 출력합니다. 다른 학생의 이름은 ‘다른 학생’으로 바꾸어 미리보기에 표시합니다.</p>`,async f=>{C.dates(f.get('from'),f.get('to'));reportPreview(s,f.get('from'),f.get('to'))},'인쇄 내용 확인')}
function reportPreview(s,from,to){const records=C.reportRecords(db(),s.id,from,to);modal('인쇄 전 내용 확인',`<div class="notice">각 기록에서 이 학생과 관계없는 내용·다른 학생의 개인정보를 제거해 주세요. 이름 자동 가림만으로 본문 속 모든 개인정보를 판단할 수는 없습니다. 수정한 내용은 이번 보고서에만 적용됩니다.</div>${records.map((r,i)=>`<div class="record"><strong>${esc(r.date)} ${esc(r.period)} · ${esc(kindLabel(r.kind))}</strong>${textarea('이 학생의 기록','text-'+i,C.redact(r.text,db(),s.id))}${textarea('이 학생에 대한 조치','action-'+i,C.redact(r.action,db(),s.id))}</div>`).join('')||empty('인쇄할 기록이 없습니다.')}${checkbox('이 학생의 내용만 남겼으며, 외부에 전달할 개인정보를 확인했습니다.','reviewed')}`,async f=>{if(!f.get('reviewed'))throw Error('전달 내용을 확인한 뒤 체크해 주세요.');const safe=records.map((r,i)=>({...r,text:f.get('text-'+i),action:f.get('action-'+i)}));closeModal();showPrint(s,from,to,safe)},'보고서 열기')}
function showPrint(s,from,to,records){const score=C.scores(db(),s.id,from,to),counts=Object.fromEntries(C.KINDS.map(k=>[k,records.filter(r=>r.kind===k).length]));const root=document.createElement('div');root.className='print-root';root.innerHTML=`<div class="report-page"><div class="no-print row">${btn('인쇄 / PDF 저장',()=>window.print(),'primary')}${btn('보고서 닫기',()=>{root.remove();document.body.classList.remove('report-open')})}<small>브라우저 인쇄 설정의 머리글·바닥글을 끄면 출력 시각과 주소가 빠집니다.</small></div><p style="margin-top:20px">오늘의 별 · ${esc(settings().className)}</p><h1>${esc(settings().reportHeader)}</h1><p>${esc(s.no)}. ${esc(s.name)} ${s.group?'· '+esc(s.group)+'모둠':''}<br>${esc(from)} ~ ${esc(to)}</p><h2>기간 요약</h2><p>총 ${records.length}건 · 칭찬 ${counts['칭찬']} · 조언 ${counts['지도']} · 기록 ${counts['관찰']} · 추가 기록 ${counts['추가기록']}</p><table><thead><tr>${C.AREAS.map(a=>`<th>${esc(a)}</th>`).join('')}</tr></thead><tbody><tr>${C.AREAS.map(a=>`<td>${records.filter(r=>r.areas.includes(a)).reduce((n,r)=>n+C.delta(r),0)}</td>`).join('')}</tr></tbody></table><h2 style="margin-top:22px">학교생활 기록</h2>${records.map(r=>`<article class="record"><strong>${esc(r.date)} ${esc(r.period)} · ${esc(kindLabel(r.kind))}</strong><div class="body">${esc(r.text)}</div>${r.action?`<p class="body" style="margin-top:8px">조치: ${esc(r.action)}</p>`:''}</article>`).join('')||'<p>해당 기간에 기록이 없습니다.</p>'}</div>`;document.querySelector('.print-root')?.remove();document.body.append(root);document.body.classList.add('report-open');root.scrollIntoView();}
function seatsView(){const st=settings(),rows=Number(st.seatRows),cols=Number(st.seatCols);const order=Array.from({length:rows},(_,i)=>st.frontTop?i:rows-1-i);return `<div class="toolbar"><h2>자리</h2><div class="row">${btn('교실 앞 '+(st.frontTop?'아래로':'위로'),()=>commit([up('settings',{...st,frontTop:!st.frontTop})]))}<small>칸을 눌러 배치 · 학생 버튼으로 기록 확인</small></div></div>${st.frontTop?'<div class="front">교실 앞</div>':''}<div class="seats" style="grid-template-columns:repeat(${cols},minmax(90px,1fr));overflow:auto">${order.flatMap(row=>Array.from({length:cols},(_,col)=>{const s=students().find(s=>s.seat?.row===row&&s.seat?.col===col);return `<div class="seat"><small>${row+1}행 ${col+1}열</small>${s?btn(esc(name(s.id)),()=>studentDetail(s.id),'primary'):''}${btn(s?'배치 변경':'학생 배치',()=>seatEditor(row,col))}</div>`})).join('')}</div>${!st.frontTop?'<div class="front" style="margin-top:15px">교실 앞</div>':''}`}
function seatEditor(row,col){const current=students().find(s=>s.seat?.row===row&&s.seat?.col===col);modal(`${row+1}행 ${col+1}열 배치`,select('학생 · 기존 자리가 있으면 서로 교환합니다.','student',[['','빈자리'],...students().map(s=>[s.id,name(s.id)])],current?.id||''),async f=>{const id=f.get('student'),next=db().students.find(s=>s.id===id),ops=[];if(current&&current.id!==id)ops.push(up('students',{...current,seat:next?.seat||null}));if(next)ops.push(up('students',{...next,seat:{row,col}}));await commit(ops);closeModal()})}
function settingsView(){const st=settings(),bytes=new Blob([JSON.stringify(db())]).size;return `<div class="toolbar"><div><h2>설정</h2><small>학급과 기록 방식을 선생님께 맞추세요.</small></div></div><div class="grid2"><section class="panel"><h3>학급 · 화면</h3><form id="settings-form"><div class="formgrid">${input('학급 이름','className',st.className,'text','required')}${input('학년도','academicYear',st.academicYear,'number','min="2020" max="2100" required')}${input('학교명 · 학생 아이디 준비용','schoolName',st.schoolName||'')}${select('교실 화면 이름 표기','nameDisplayMode',[['number','번호만 · 기본'],['masked','이름 가림 · 김●수'],['alias','교사가 정한 별칭']],st.nameDisplayMode)}${input('자리 행','seatRows',st.seatRows,'number','min="1" max="12" required')}${input('자리 열','seatCols',st.seatCols,'number','min="1" max="12" required')}<div class="span2">${input('보고서 제목','reportHeader',st.reportHeader)}</div><div>${checkbox('시간표에 선생님 표시','showTeacher',st.timetableDisplay.showTeacher)}</div><div>${checkbox('시간표에 장소 표시','showLocation',st.timetableDisplay.showLocation)}</div><div class="span2">${input('교실 화면 해제 비밀번호 · 새로 설정할 때만 입력','classroomPin','','password','minlength="4" autocomplete="new-password"')}</div>${(st.periodTimes||[]).map((time,i)=>input(`${i+1}교시 시간 · 표시용`,'period-'+i,time)).join('')}</div><button class="primary" style="margin-top:15px">설정 저장</button></form></section><section class="panel"><h3>백업과 복원</h3><p class="muted">${store.mode==='cloud'?'학생의 텍스트 자료는 외부 서버인 수파베이스에 저장됩니다.':'체험 모드 자료는 현재 브라우저에만 저장됩니다.'}</p><p>학급 데이터 약 <strong>${(bytes/1024).toFixed(1)} KB</strong><br><small>텍스트 JSON 기준 추정치입니다. 실제 DB·백업·인증 저장량은 수파베이스 대시보드에서 확인하세요.</small></p><p class="muted">마지막 파일 백업: ${st.lastBackupAt?esc(localTime(st.lastBackupAt)):'없음'}</p><div class="row">${btn('전체 JSON 내려받기',downloadBackup,'primary')}${btn('JSON 가져오기',()=>$('#backup-input').click())}${btn('클라우드에 한 벌 더 저장',async()=>{await store.cloudBackup();toast('클라우드 백업을 저장했습니다. 최근 2세대를 보관합니다.')})}${btn('클라우드 백업 복구',cloudRestore)}</div><input id="backup-input" type="file" accept="application/json,.json" hidden><div class="notice">사진·음성은 저장하지 않습니다. 백업 파일에는 학생 기록이 포함되므로 안전한 곳에 보관하세요.</div><h3 style="margin-top:22px">학년도 전환</h3><p class="muted">현재 학생을 새 고유 ID로 복제합니다. 지난 기록은 보존하고 새 학생에게는 연결하지 않습니다.</p>${btn('다음 학년으로 이어 가기',rollover)}</section></div><section class="panel"><div class="toolbar"><h3>학생 명단</h3><div class="row">${btn('명단 붙여넣기',rosterPaste,'primary')}${btn('+ 학생',()=>studentEditor())}${btn('나간 학생 보기',removedStudents)}</div></div><div class="table-wrap"><table><thead><tr><th>번호</th><th>이름</th><th>모둠</th><th>별칭</th><th></th></tr></thead><tbody>${students().map(s=>`<tr><td>${s.no}</td><td>${esc(s.name)}</td><td>${esc(s.group)}</td><td>${esc(s.alias||'')}</td><td><div class="row">${btn('수정',()=>studentEditor(s))}${btn('삭제',async()=>{if(confirm(`${s.name} 학생을 명단에서 뺄까요? 기록과 과제 상태는 보존합니다.`))await commit([up('students',{...s,deletedAt:C.now(),seat:null})])},'danger')}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="toolbar"><h3>과목 · 전담 설정</h3>${btn('+ 과목',()=>subjectEditor())}</div><div class="table-wrap"><table><thead><tr><th>과목</th><th>구분</th><th>장소</th><th>담당 교사</th><th></th></tr></thead><tbody>${db().subject_rules.map(s=>`<tr><td><span class="badge" style="background:${esc(s.color)}">${esc(s.code)}</span></td><td>${s.isSpecialist?'전담':'담임'} · ${esc(s.defaultType)}</td><td>${esc(s.location)}</td><td>${esc(s.teacherName)}</td><td>${btn('수정',()=>subjectEditor(s))}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="toolbar"><h3>태그 · 파서 별칭 사전</h3>${btn('+ 태그',()=>tagEditor())}</div><div class="table-wrap"><table><thead><tr><th>태그</th><th>성격</th><th>영역</th><th>별칭</th><th></th></tr></thead><tbody>${db().tags.filter(t=>!t.deletedAt).map(t=>`<tr><td>${esc(t.label)}</td><td>${esc(kindLabel(t.kind))}</td><td>${esc(t.area)}</td><td>${esc(t.aliases.join(', '))}</td><td><div class="row">${btn('수정',()=>tagEditor(t))}${btn('삭제',async()=>{if(confirm('태그를 삭제할까요? 기존 기록은 그대로 남습니다.'))await commit([up('tags',{...t,deletedAt:C.now()})])},'danger')}</div></td></tr>`).join('')}</tbody></table></div></section>${bindLater('settings-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target),pin=f.get('classroomPin');const next={...st,className:f.get('className').trim(),academicYear:Number(f.get('academicYear')),schoolName:f.get('schoolName').trim(),nameDisplayMode:f.get('nameDisplayMode'),seatRows:Number(f.get('seatRows')),seatCols:Number(f.get('seatCols')),reportHeader:f.get('reportHeader'),periodTimes:Array.from({length:6},(_,i)=>f.get('period-'+i)),timetableDisplay:{...st.timetableDisplay,showTeacher:!!f.get('showTeacher'),showLocation:!!f.get('showLocation')}};if(pin)next.classroomPinHash=await hashPin(pin);await commit([up('settings',next)])})}${bindLater('backup-input','change',e=>importBackup(e.target.files[0]))}`}
async function hashPin(pin){if(!crypto.subtle)throw Error('교실 비밀번호는 HTTPS 또는 localhost 접속에서 설정하세요.');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('startoday-classroom:'+pin));return Array.from(new Uint8Array(bytes)).map(x=>x.toString(16).padStart(2,'0')).join('')}
function rosterPaste(){modal('명단 붙여넣기',`${textarea('번호 이름 모둠 · 탭/쉼표/공백 구분 모두 인식','roster','')}<p class="muted">예: 1 김민준 1모둠<br>51 이서연 2모둠<br>이름만 붙이면 다음 번호부터 제안합니다.</p>`,async f=>{const rows=C.parseRoster(f.get('roster'),Math.max(0,...students().map(s=>s.no))+1);if(!rows.length)throw Error('명단을 붙여 넣으세요.');rosterPreview(rows)},'등록 미리보기')}
function rosterPreview(rows){modal('명단 확인 · 수정 후 한 번에 등록',`<p class="muted">동명이인도 고유 ID로 각각 등록합니다. 번호는 입력한 그대로 유지합니다.</p><div class="table-wrap"><table><thead><tr><th>번호</th><th>이름</th><th>모둠</th></tr></thead><tbody>${rows.map((s,i)=>`<tr><td><input aria-label="${i+1}행 번호" name="no-${i}" type="number" min="1" required value="${s.no}" style="width:75px"></td><td><input aria-label="${i+1}행 이름" name="name-${i}" required value="${esc(s.name)}"></td><td><input aria-label="${i+1}행 모둠" name="group-${i}" value="${esc(s.group)}"></td></tr>`).join('')}</tbody></table></div>`,async f=>{const next=rows.map((_,i)=>({id:C.uid(),no:Number(f.get('no-'+i)),name:f.get('name-'+i).trim(),group:f.get('group-'+i),academicYear:settings().academicYear,seat:null,createdAt:C.now()}));if(next.some(s=>!s.name||!Number.isInteger(s.no)||s.no<1))throw Error('이름과 번호를 확인하세요.');const all=[...students(),...next],seen=new Set(),duplicate=all.some(s=>seen.has(s.no)?true:(seen.add(s.no),false));if(duplicate&&!confirm('중복 번호가 있습니다. 그대로 등록할까요?'))return;for(const s of next){const old=db().students.find(x=>x.deletedAt&&x.no===s.no&&x.name===s.name);if(old&&confirm(`${s.no}. ${s.name}: 기존 학생의 기록과 다시 연결할까요?`)){s.id=old.id;s.createdAt=old.createdAt;s.deletedAt=null}}await commit(next.map(s=>up('students',s)));closeModal()},'명단 등록')}
function removedStudents(){modal('나간 학생 · 기록은 보존됩니다.',db().students.filter(s=>s.deletedAt).map(s=>`<div class="row between record"><span>${esc(s.no)}. ${esc(s.name)} (${s.academicYear})</span><div class="row">${btn('기록 보기',()=>studentDetail(s.id))}${btn('복귀',async()=>{await commit([up('students',{...s,deletedAt:null})]);removedStudents()})}</div></div>`).join('')||empty('나간 학생이 없습니다.'))}
function tagEditor(t=null){const row=t||{id:C.uid(),label:'',kind:'칭찬',area:null,aliases:[]};modal(t?'태그 수정':'태그 추가',`<div class="formgrid">${input('태그 이름','label',row.label,'text','required')}${select('성격','kind',[['칭찬','칭찬'],['지도','조언']],row.kind)}${select('기본 영역','area',[['','미지정'],...C.AREAS],row.area||'')}${input('별칭 · 쉼표로 구분','aliases',row.aliases.join(', '))}</div>`,async f=>{await commit([up('tags',{...row,label:f.get('label').trim(),kind:f.get('kind'),area:f.get('area')||null,aliases:f.get('aliases').split(',').map(x=>x.trim()).filter(Boolean)})]);closeModal()})}
function subjectEditor(s=null){const row=s||{id:C.uid(),code:'',label:'',color:'#E0F2FE',isSpecialist:false,location:'',teacherName:'',defaultType:'일반',sortOrder:db().subject_rules.length,teacherHistory:[]};modal(s?'과목 설정':'과목 추가',`<div class="formgrid">${input('과목명 · 코드','code',row.code,'text','required')}${input('한 글자 축약명','label',row.label)}${input('과목 색상','color',row.color,'color')}${select('기본 구분','defaultType',['일반','외부','강사','다른장소'],row.defaultType)}${checkbox('전담 과목','isSpecialist',row.isSpecialist)}${input('장소','location',row.location)}${input('담당 교사명','teacherName',row.teacherName)}${input('담당 교사 변경 적용일','teacherFrom',date,'date','required')}${input('정렬 순서','sortOrder',row.sortOrder,'number')}</div><p class="muted">과목명 변경 시 기존 시간표도 함께 변경합니다. 담당 교사 변경은 적용일 이후에만 반영됩니다.</p>`,async f=>{const code=f.get('code').trim();if(db().subject_rules.some(x=>x.id!==row.id&&x.code===code))throw Error('같은 과목명이 있습니다.');const teacher=f.get('teacherName'),history=[...(row.teacherHistory||[])];if(!history.length)history.push({from:'1900-01-01',name:row.teacherName||''});if(teacher!==row.teacherName)history.push({from:f.get('teacherFrom'),name:teacher});const next={...row,code,label:f.get('label')||code[0],color:f.get('color'),defaultType:f.get('defaultType'),isSpecialist:!!f.get('isSpecialist'),location:f.get('location'),teacherName:teacher,teacherHistory:history,sortOrder:Number(f.get('sortOrder'))};let ops=[up('subject_rules',next)];if(s&&s.code!==code){ops.push(...db().timetables.filter(t=>t.subjectCode===s.code).map(t=>up('timetables',{...t,subjectCode:code})));const template={...settings().weeklyTemplate};for(const key in template)if(template[key]===s.code)template[key]=code;ops.push(up('settings',{...settings(),weeklyTemplate:template}))}await commit(ops);closeModal()})}
function saveFile(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function backupObject(){return {app:'startoday',version:1,exportedAt:C.now(),data:structuredClone(db())}}
async function downloadBackup(){saveFile(`startoday-backup-${C.today().replaceAll('-','')}.json`,JSON.stringify(backupObject(),null,2));await commit([up('settings',{...settings(),lastBackupAt:C.now()})],'백업 파일 다운로드를 시작했습니다.')}
async function importBackup(file){if(!file)return;if(file.size>20*1024*1024)throw Error('백업 파일은 20MB 이하만 불러올 수 있습니다.');const imported=C.validateBackup(JSON.parse(await file.text()));restoreDialog(imported)}
function restoreDialog(imported){modal('백업 복원',`<p>학생 ${imported.students.length}명 · 기록 ${imported.records.length}건</p>${select('복원 방식','mode',[['replace','현재 자료를 파일 내용으로 대체 · 기본'],['merge','고유 ID로 합치기 · 같은 ID는 파일 내용 우선']],'replace')}<div class="notice">복원 직전 자료는 자동으로 백업 파일을 내려받습니다. 같은 번호·이름이어도 ID가 다르면 별도 학생입니다.</div>`,async f=>{if(!confirm('현재 자료를 백업한 뒤 복원할까요?'))return;saveFile(`startoday-before-restore-${Date.now()}.json`,JSON.stringify(backupObject(),null,2));const replace=f.get('mode')==='replace';let ops=[];for(const t of C.TABLES){if(replace)ops.push(...db()[t].map(x=>({table:t,id:x.id,remove:true})));ops.push(...imported[t].map(x=>up(t,x)))}await commit(ops,'복원했습니다.');selected=[];closeModal();render()})}
async function cloudRestore(){if(store.mode!=='cloud')throw Error('구글 로그인 후 사용할 수 있습니다.');const {data,error}=await store.client.from('startoday_backups').select('id,created_at,data').eq('class_id',store.classId).order('created_at',{ascending:false}).limit(2);if(error)throw error;modal('클라우드 백업 복구',data.map(b=>`<div class="record row between"><span>${esc(localTime(b.created_at))}</span>${btn('이 백업 선택',()=>restoreDialog(C.validateBackup({app:'startoday',version:1,data:b.data.data})))}</div>`).join('')||empty('아직 저장한 백업이 없습니다.'))}
function rollover(){modal('다음 학년으로 이어 가기',`${input('새 학년도','year',Number(settings().academicYear)+1,'number','required min="2020" max="2100"')}<p class="muted">현재 학생은 나간 학생으로 보관하고, 명단을 새로운 ID로 복제합니다. 현재 과제·루틴은 중단합니다. 지난 기록과 과제 상태는 보존합니다.</p>${students().map(s=>`<div class="row" style="margin-bottom:8px"><span style="min-width:100px">${esc(s.name)}</span><input aria-label="${esc(s.name)} 새 번호" name="no-${s.id}" type="number" min="1" value="${s.no}" required style="width:90px"></div>`).join('')}`,async f=>{if(!confirm('새 학년도 명단으로 전환할까요?'))return;saveFile(`startoday-before-year-${Date.now()}.json`,JSON.stringify(backupObject(),null,2));const year=Number(f.get('year'));const ops=[up('settings',{...settings(),academicYear:year})];for(const s of students()){ops.push(up('students',{...s,deletedAt:C.now(),seat:null}));ops.push(up('students',{...s,id:C.uid(),no:Number(f.get('no-'+s.id)),academicYear:year,seat:null,createdAt:C.now(),studentCode:'',deletedAt:null}))}for(const a of db().assignments.filter(a=>!a.deletedAt))ops.push(up('assignments',{...a,endDate:C.addDays(date,-1)}));for(const r of db().routines.filter(r=>!r.deletedAt))ops.push(up('routines',{...r,deletedAt:C.now()}));await commit(ops);closeModal()})}
function displayName(s){if(settings().nameDisplayMode==='alias')return s.alias||`별${s.no}`;if(settings().nameDisplayMode==='masked'){const n=s.name;return s.no+'. '+(n.length<=2?n[0]+'●':n[0]+'●'.repeat(n.length-2)+n.at(-1))}return String(s.no)+'번'}
function classroom(){document.querySelector('.print-root')?.remove();document.body.classList.remove('report-open');if($('#modal').open)closeModal();selected=[];locked=true;const d=C.today();$('#app').innerHTML=`<div class="lockscreen"><div class="row between"><div><h1>오늘의 별 · ${esc(settings().className)}</h1><p>${esc(d)}</p></div><div id="class-clock" class="clock"></div></div><section class="panel"><div class="row">${db().events.filter(e=>e.date===d||e.isDday).map(e=>badge(e.title+(e.isDday?' '+C.dday(e.date,d):''))).join('')||'<p>오늘 일정 없음</p>'}</div><div class="schedule" style="margin-top:14px">${timeSlots(d)}</div></section><div class="students">${students().map(s=>`<div class="student ${isUnfinished(s.id,d)?'unfinished':''}"><strong>${esc(displayName(s))}</strong><small>${C.excluded(db(),s.id,d)?'제외':isUnfinished(s.id,d)?'할 일이 남아 있어요':'오늘 할 일 완료'}</small></div>`).join('')}</div><button type="button" class="lock-exit" id="lock-exit" aria-label="교사 화면 잠금 해제">잠금 · 길게 눌러 해제</button></div>`;const tick=()=>{if($('#class-clock'))$('#class-clock').textContent=new Date().toLocaleTimeString('ko-KR',{hour12:false,timeZone:'Asia/Seoul'})};tick();clearInterval(clockTimer);clockTimer=setInterval(tick,1000);let hold;const exit=$('#lock-exit');const unlock=async()=>{if(settings().classroomPinHash){const pin=prompt('교실 화면 해제 비밀번호');if(pin===null||await hashPin(pin)!==settings().classroomPinHash){toast('비밀번호를 확인하세요.');return}}clearInterval(clockTimer);locked=false;render()};exit.onpointerdown=e=>{e.preventDefault();hold=setTimeout(()=>run(unlock),1400)};exit.onpointerup=()=>clearTimeout(hold);exit.onpointercancel=()=>clearTimeout(hold);exit.onpointerleave=()=>clearTimeout(hold);exit.ondblclick=()=>run(unlock);exit.onkeydown=e=>{if(e.ctrlKey&&e.key==='Enter')run(unlock)}}
window.addEventListener('startoday-auth',()=>{selected=[];render()});window.addEventListener('startoday-error',e=>toast(e.detail));
window.addEventListener('online',()=>toast('네트워크가 연결되었습니다. 새로고침으로 최신 자료를 확인하세요.'));
window.addEventListener('offline',()=>toast('네트워크 연결이 끊겼습니다. 클라우드 저장은 연결 후 다시 시도하세요.'));
async function boot(){$('#app').innerHTML='<div class="login"><h1>오늘의 별</h1><p>학급을 준비하고 있습니다…</p></div>';try{await store.connect();render()}catch(e){if(!store.db?.settings?.length)store.db=null;render();toast(e.message+' · SQL 적용 및 config.js 설정을 확인하세요.')}}
boot();
